'use strict';
// Synthetic feedback: original text is immutable; linking never creates a ticket or sends a reply.
const feedbackStatuses={new:['Новое','New'],reviewing:['В разборе','In review'],reviewed:['Разобрано','Reviewed']};
const feedbackCategories={problem:['Проблема','Problem'],idea:['Предложение','Suggestion'],other:['Другое','Other']};
const feedbackFixtures=[
 {id:'FB-101',uid:'U-DEMO-002',sid:'S-DEMO-002',name:'Demo Noor',venue:'Polymarket',title:['Не понимаю результат заявки','Order result is unclear'],body:'I cannot tell whether my order went through. Please make the pending state clearer.',language:'English',source:['После результата демо-сессии','After a demo session result'],date:'2026-10-23',category:'problem',status:'new',assignee:'none',ticket:null},
 {id:'FB-102',uid:'U-DEMO-005',sid:'S-DEMO-005',name:'Demo Robin',venue:'Limitless',title:['Пояснение частичного исполнения','Explain partial fills'],body:'Покажите рядом с исполненной суммой, сколько ещё осталось в заявке.',language:'Русский',source:['Форма в профиле','Profile form'],date:'2026-10-22',category:'idea',status:'reviewing',assignee:'STAFF-203',ticket:'T-102'},
 {id:'FB-103',uid:null,sid:null,name:null,venue:null,title:['Тексты первого входа','First-run copy'],body:'На первом экране хотелось бы короткий пример. Не понял, с чего начать.',language:'Русский',source:['После первой настройки','After initial setup'],date:'2026-10-21',category:'other',status:'new',assignee:'none',ticket:null}
];
const feedbackAccess=role=>supportAccess(role);
function newFeedback(){return {records:structuredClone(feedbackFixtures).map(x=>({...x,version:1,note:'',notes:[],events:[]})),id:'FB-101',q:'',status:'all',category:'all',assignee:'all',from:'2026-10-17',to:'2026-10-23',sort:'newest',drafts:{},get draft(){return this.drafts[this.id]||null;},set draft(v){this.drafts[this.id]=v;},link:null,notice:null,error:null,returnFromTicket:false,linkedContext:false,scroll:0};}
let feedback=newFeedback();
const fl=(dict,k)=>pl(...dict[k]);
const fb=(ru,en,action,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-feedback="${action}" ${extra}>${pl(ru,en)}</button>`;
const feedbackAllowed=x=>Boolean(account?.logged&&feedbackAccess(state.role).read&&(!actor().limited||x.uid==='U-DEMO-002'));
const feedbackCurrent=()=>feedback.records.find(x=>x.id===feedback.id&&feedbackAllowed(x));
function feedbackRows(){const q=feedback.q.trim().toLowerCase();return feedback.records.filter(x=>feedbackAllowed(x)&&(!q||[x.id,...x.title,x.name||'',x.body].join(' ').toLowerCase().includes(q))&&['status','category','assignee'].every(k=>feedback[k]==='all'||feedback[k]===x[k])&&x.date>=feedback.from&&x.date<=feedback.to).sort((a,b)=>a.date.localeCompare(b.date)*(feedback.sort==='oldest'?1:-1));}
function feedbackSelect(id,label,values,current,disabled=false){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" ${disabled?'disabled':''}>${options(values,current)}</select></div>`;}
const feedbackAssignees=()=>[['none',pl('Не назначен','Unassigned')],['STAFF-203',supportWho('STAFF-203')],['STAFF-206',supportWho('STAFF-206')]];
const feedbackTabs=()=>`<div class="tabs" aria-label="${pl('Раздел поддержки','Support section')}">${button(pl('Обращения','Conversations'),'support')}${fb('Обратная связь','Feedback','list','aria-current="page"')}</div>`;
function feedbackList(){if(!feedbackAccess(state.role).read)return supportDenied();const rows=feedbackRows();return feedbackTabs()+supportHeading(pl('Обратная связь','Feedback'),pl('Разбирайте отзывы о продукте. Если нужен личный ответ, перейдите в связанное обращение.','Review product feedback. For a personal reply, open the linked support conversation.'))+`<section class="panel support-filters"><div class="field"><label for="feedback-q">${pl('Поиск по теме, тексту или ID','Find by topic, text or ID')}</label><input id="feedback-q" type="search" value="${escape(feedback.q)}"></div>${['status','category','assignee'].map(k=>feedbackSelect('feedback-'+k,pl(...({status:['Статус','Status'],category:['Категория','Category'],assignee:['Ответственный','Assignee']}[k])),[['all',pl('Все','All')],...(k==='assignee'?feedbackAssignees():Object.keys(k==='status'?feedbackStatuses:feedbackCategories).map(v=>[v,fl(k==='status'?feedbackStatuses:feedbackCategories,v)]))],feedback[k])).join('')}<div class="field"><label for="feedback-from">${pl('С даты · UTC','From · UTC')}</label><input id="feedback-from" type="date" value="${feedback.from}"></div><div class="field"><label for="feedback-to">${pl('По дату · UTC','To · UTC')}</label><input id="feedback-to" type="date" value="${feedback.to}"></div>${fb('Сбросить фильтры','Reset filters','reset')}${feedback.error?`<p role="alert">${pl(...feedback.error)}</p>`:''}</section><section class="panel"><div class="support-table-top"><h2>${pl('Отзывы','Items')} · ${rows.length}</h2>${feedbackSelect('feedback-sort',pl('Порядок','Sort'),[['newest',pl('Сначала новые','Newest first')],['oldest',pl('Сначала старые','Oldest first')]],feedback.sort)}</div><div class="table-wrap"><table class="feedback-table"><thead><tr>${['Тема|Topic','Категория|Category','Статус|Status','Ответственный|Assignee','Получено · UTC|Received · UTC','Поддержка|Support'].map(s=>`<th scope="col">${pl(...s.split('|'))}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${fb(...x.title,'open',`data-id="${x.id}"`)}<small>${x.id} · ${x.name||pl('Контекст не передан','Context not provided')}</small></td><td>${fl(feedbackCategories,x.category)}</td><td><span class="badge">${fl(feedbackStatuses,x.status)}</span></td><td>${supportWho(x.assignee)}</td><td>${x.date}</td><td>${x.ticket?fb(x.ticket,x.ticket,'ticket',`data-id="${x.id}"`):pl('Не связано','Not linked')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?`<div class="empty"><h2>${pl('Отзывов по этому отбору нет','No matching feedback')}</h2><p>${pl('Измените поиск или сбросьте фильтры.','Change the search or reset filters.')}</p>${fb('Сбросить фильтры','Reset filters','reset')}</div>`:''}</section><p class="muted">${pl('Три учебных отзыва. Показаны все доступные результаты; даты — фиксированный снимок.','Three synthetic items. All permitted results are shown; dates are a fixed snapshot.')}</p>`;}
function feedbackDetail(){const x=feedbackCurrent();if(!x)return supportDenied();const write=feedbackAccess(state.role).write,d=feedback.draft||x;return fb('К отзывам','Back to feedback','back')+supportHeading(pl(...x.title),`${x.id} · ${x.date} · ${pl('Получено · UTC','Received · UTC')}`)+`${feedback.notice?`<p class="support-notice" role="status">${pl(...feedback.notice)}</p>`:''}${!write?`<p class="support-notice">${pl('Только просмотр. Обработка и внутренние заметки недоступны.','Read only. Processing and internal notes are unavailable.')}</p>`:''}<div class="support-layout"><div><section class="panel feedback-original"><h2>${pl('Что написал пользователь','Original feedback')}</h2><p class="feedback-quote">${escape(x.body)}</p><dl class="feedback-meta"><dt>${pl('Язык оригинала','Original language')}</dt><dd>${x.language}</dd><dt>${pl('Откуда получено','Source')}</dt><dd>${pl(...x.source)}</dd></dl><p class="muted">${pl('Текст автора сохраняется без изменений и автоматического перевода.','The author’s text stays unchanged and is not automatically translated.')}</p></section><section class="panel"><h2>${pl('Обработка отзыва','Feedback processing')}</h2><form id="feedback-form">${['category','status','assignee'].map(k=>feedbackSelect('feedback-edit-'+k,pl(...({category:['Категория','Category'],status:['Статус отзыва','Feedback status'],assignee:['Ответственный','Assignee']}[k])),k==='assignee'?feedbackAssignees():Object.keys(k==='status'?feedbackStatuses:feedbackCategories).map(v=>[v,fl(k==='status'?feedbackStatuses:feedbackCategories,v)]),d[k],!write)).join('')}<p class="muted">${pl('«Разобрано» означает завершение обработки отзыва. Это не исправление ошибки и не закрытие обращения.','“Reviewed” means feedback processing is complete. It does not mean a bug is fixed or a conversation is closed.')}</p>${feedback.error?`<p class="account-error" role="alert">${pl(...feedback.error)}</p>`:''}${write?`<button class="btn primary" type="submit">${pl('Сохранить обработку','Save processing')}</button> ${fb('Отменить изменения','Discard changes','discard')}`:''}</form></section>${write?`<section class="panel"><h2>${pl('Внутренние заметки','Internal notes')}</h2>${x.notes.map(n=>`<article class="support-message internal"><strong>${escape(n.author)}</strong><p>${escape(n.body)}</p></article>`).join('')}<form id="feedback-note-form"><label for="feedback-note">${pl('Только сотрудникам — пользователь не увидит','Staff only — hidden from the user')}</label><textarea id="feedback-note" rows="3" maxlength="2000">${escape(x.note)}</textarea>${fb('Добавить заметку','Add note','note')}</form></section>`:''}<details class="panel"><summary>${pl('История обработки','Processing history')} · ${x.events.length}</summary>${x.events.map(e=>`<p>${escape(e.author)} · ${escape(e.time)} · v${e.version}<br>${escape(pl(...e.label))}</p>`).join('')||`<p>${pl('В этом учебном сеансе изменений ещё нет.','No changes in this synthetic session yet.')}</p>`}</details></div><aside class="support-context"><section class="panel"><h2>${pl('Переданный контекст','Provided context')}</h2>${x.uid?`<p><strong>${x.name}</strong><br>${x.uid}<br>${x.venue} · ${pl('Демо','Demo')}<br>${x.sid}</p>${fb('Открыть пользователя','Open user','user')}${fb('Открыть сессию','Open session','session')}`:`<p>${pl('Пользователь, площадка и сессия не переданы. Связь по похожему имени или теме недопустима.','User, venue and session were not provided. A similar name or topic is not enough to link records.')}</p>`}</section><section class="panel"><h2>${pl('Связь с поддержкой','Support connection')}</h2>${x.ticket?`<p>${x.ticket} · ${pl('Связано с обращением','Linked conversation')}</p>${fb('Открыть обращение','Open conversation','ticket',`data-id="${x.id}"`)}<p class="muted">${pl('Ответ пользователю отправляется в переписке. Статусы отзыва и обращения независимы.','Reply in the conversation. Feedback and conversation statuses are independent.')}</p>`:`<p>${pl('Обращение не связано. Отзыв сам по себе не обещает личного ответа.','No linked conversation. Feedback alone does not promise a personal reply.')}</p>${write&&x.uid?fb('Связать с обращением','Link conversation','choose'):''}`}${feedback.link&&write&&!x.ticket?feedbackLinkForm(x):''}</section>${write?`<details class="panel"><summary>${pl('Учебная проверка конфликта','Test a conflicting update')}</summary><p>${pl('Имитирует новую версию записи. Ваш черновик останется для проверки.','Simulates a newer record version. Your draft remains for review.')}</p>${fb('Имитировать изменение другим сотрудником','Simulate another teammate’s change','conflict')}</details>`:''}</aside></div>`;}
function feedbackLinkForm(x){const matches=support.records.filter(t=>supportAllowed(t)&&t.uid===x.uid&&t.sid===x.sid&&t.venue===x.venue);return `<div class="feedback-link"><h3>${pl('Проверьте связь','Check the connection')}</h3>${feedback.error?`<p role="alert">${pl(...feedback.error)}</p>`:''}${feedbackSelect('feedback-ticket',pl('Существующее обращение','Existing conversation'),[['',pl('Выберите обращение','Choose a conversation')],...matches.map(t=>[t.id,`${t.id} · ${t.name} · ${t.sid}`])],feedback.link.ticket)}<p>${pl('Создаст только связь. Новый тикет и сообщение не создаются; статусы не меняются.','Adds a link only. No new conversation or message; statuses stay unchanged.')}</p>${fb('Подтвердить связь','Confirm link','link','',true)} ${fb('Отмена','Cancel','cancel-link')}</div>`;}
function feedbackEvent(x,ru,en){x.version++;x.events.push({author:accountName()+' · '+actor().id,time:new Date().toISOString(),version:x.version,label:[ru,en]});}
function feedbackSave(){const x=feedbackCurrent();if(!x||!feedbackAccess(state.role).write)return false;const d=feedback.draft;if(!d)return true;if(d.version!==x.version){feedback.error=['Запись изменилась. Проверьте текущие значения и отмените устаревшие изменения перед повторной правкой. Черновик заметки сохранён.','The record changed. Review current values and discard outdated changes before editing again. Your note draft is preserved.'];return false;}if(!feedbackStatuses[d.status]||!feedbackCategories[d.category]||!feedbackAssignees().some(a=>a[0]===d.assignee))return false;const changes=['category','status','assignee'].filter(k=>x[k]!==d[k]);if(changes.length){const labels=changes.map(k=>[k,x[k],d[k]]);Object.assign(x,{category:d.category,status:d.status,assignee:d.assignee});feedbackEvent(x,labels.map(([k,a,b])=>`${({category:'Категория',status:'Статус',assignee:'Ответственный'})[k]}: ${k==='assignee'?supportWho(a):({category:feedbackCategories,status:feedbackStatuses})[k][a][0]} → ${k==='assignee'?supportWho(b):({category:feedbackCategories,status:feedbackStatuses})[k][b][0]}`).join('; '),labels.map(([k,a,b])=>`${k}: ${a} → ${b}`).join('; '));}feedback.draft=null;feedback.error=null;feedback.notice=['Обработка сохранена. Пользователю ничего не отправлялось.','Processing saved. Nothing was sent to the user.'];return true;}
function feedbackAction(action,el={dataset:{}}){feedback.error=null;feedback.notice=null;if(['open','ticket'].includes(action)&&el.dataset.id){const target=feedback.records.find(x=>x.id===el.dataset.id&&feedbackAllowed(x));if(!target)return;feedback.id=target.id;}const x=feedbackCurrent();if(action==='list'||action==='back'){feedback.link=null;feedback.returnFromTicket=false;navigate('feedback');window.scrollTo(0,feedback.scroll);return;}if(action==='reset'){Object.assign(feedback,{q:'',status:'all',category:'all',assignee:'all',from:'2026-10-17',to:'2026-10-23'});render();return;}if(!x)return;if(action==='open'){feedback.draft??={category:x.category,status:x.status,assignee:x.assignee,version:x.version};feedback.link=null;feedback.scroll=window.scrollY;navigate('feedbackItem');return;}if(action==='ticket'&&x.ticket){const t=support.records.find(t=>t.id===x.ticket&&supportAllowed(t));if(!t)return;support.id=t.id;support.statusDraft=null;support.assigneeDraft=null;support.linked=false;feedback.returnFromTicket=true;feedback.linkedContext=false;navigate('ticket');return;}if(action==='return'){feedback.returnFromTicket=false;feedback.linkedContext=false;navigate('feedbackItem');return;}if(['user','session'].includes(action)&&x.uid){support.linked=false;feedback.linkedContext=true;state.userId=x.uid;state.sessionId=x.sid;state.tab='overview';navigate(action);return;}if(!feedbackAccess(state.role).write)return;if(action==='discard'){feedback.draft=null;feedback.notice=['Показаны текущие сохранённые значения.','Current saved values are shown.'];}if(action==='choose'&&x.uid&&!x.ticket)feedback.link={ticket:'',version:x.version};if(action==='cancel-link')feedback.link=null;if(action==='link'&&feedback.link){const t=support.records.find(t=>t.id===feedback.link.ticket&&supportAllowed(t));if(x.ticket){feedback.link=null;return;}if(x.version!==feedback.link.version){feedback.error=['Отзыв изменился. Откройте выбор обращения заново.','Feedback changed. Open the conversation picker again.'];}else if(!t||!x.uid||t.uid!==x.uid||t.sid!==x.sid||t.venue!==x.venue){feedback.error=['Выберите обращение с тем же пользователем, площадкой и сессией.','Choose a conversation with the same user, venue and session.'];}else{x.ticket=t.id;feedbackEvent(x,'Добавлена связь с '+t.id,'Linked to '+t.id);feedback.link=null;if(feedback.draft?.version===x.version-1)feedback.draft.version=x.version;feedback.notice=['Связь сохранена. Сообщение не отправлено; статусы прежние.','Link saved. No message sent; statuses unchanged.'];}}if(action==='note'){if(!x.note.trim())feedback.error=['Введите текст заметки.','Enter a note.'];else{x.notes.push({body:x.note.trim(),author:accountName()+' · '+actor().id});x.note='';feedbackEvent(x,'Добавлена внутренняя заметка','Internal note added');if(feedback.draft?.version===x.version-1)feedback.draft.version=x.version;}}if(action==='conflict'){feedback.draft??={category:x.category,status:x.status,assignee:x.assignee,version:x.version};x.version++;feedback.notice=['Учебная запись получила новую версию. При сохранении устаревший черновик не заменит её.','The sample record has a new version. Saving an outdated draft will not overwrite it.'];}render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-feedback]');if(b&&!b.disabled)feedbackAction(b.dataset.feedback,b);});
document.addEventListener('input',e=>{if(e.target.id==='feedback-note'){const x=feedbackCurrent();if(x&&feedbackAccess(state.role).write)x.note=e.target.value;}if(e.target.id==='feedback-q'){feedback.q=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#feedback-q');input.focus();if(pos!==null)input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='feedback-ticket'&&feedback.link)feedback.link.ticket=v;else if(id.startsWith('feedback-edit-')){const x=feedbackCurrent();if(x&&feedbackAccess(state.role).write){feedback.draft??={category:x.category,status:x.status,assignee:x.assignee,version:x.version};feedback.draft[id.slice(14)]=v;}}else if(id.startsWith('feedback-')){const k=id.slice(9);if(['status','category','assignee','sort','from','to'].includes(k)){if(['from','to'].includes(k)&&(!v||(k==='from'?v>feedback.to:v<feedback.from))){feedback.error=['Проверьте порядок дат.','Check the date order.'];render();return;}feedback[k]=v;feedback.error=null;render();}}});
document.addEventListener('submit',e=>{if(e.target.id==='feedback-form'){e.preventDefault();feedbackSave();render();}if(e.target.id==='feedback-note-form'){e.preventDefault();feedbackAction('note');}});

function feedbackTicketLinks(){if(feedback.returnFromTicket)return "";return feedback.records.filter(x=>feedbackAllowed(x)&&x.ticket===support.id).map(x=>fb('Отзыв '+x.id,'Feedback '+x.id,'open',`data-id="${x.id}"`)).join('');}
